create or replace function private.schoolpro_module_allowed(target_school uuid, required_permission text) returns boolean language sql stable security invoker set search_path='' as $$
select case
when auth.uid() is null or not exists(select 1 from public.profiles p where p.id=auth.uid() and p.status::text='active') then false
when exists(select 1 from public.schoolpro_schools s where s.id=target_school and s.owner_id=auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=target_school and m.user_id=auth.uid()) or private.is_admin()
then required_permission=any(public.schoolpro_user_permissions(target_school))
else true end;
$$;
revoke all on function private.schoolpro_module_allowed(uuid,text) from public,anon;
grant execute on function private.schoolpro_module_allowed(uuid,text) to authenticated;
