create or replace function public.request_account_deletion(p_reason text default null)
returns public.account_deletion_requests
language plpgsql
security definer
set search_path=''
as $$
declare v_profile public.profiles; v_request public.account_deletion_requests;
begin
  select * into v_profile from public.profiles where id=(select auth.uid()) for update;
  if not found then raise exception 'Authenticated profile not found.'; end if;
  if v_profile.status <> 'active' then raise exception 'Only an active account can submit a deletion request.'; end if;
  if v_profile.role <> 'customer'::public.user_role then raise exception 'Administrator accounts cannot use the customer account-deletion workflow.'; end if;

  select * into v_request from public.account_deletion_requests
   where user_id=v_profile.id and status='pending' order by requested_at desc limit 1;
  if found then return v_request; end if;

  insert into public.account_deletion_requests(user_id,status,reason)
  values(v_profile.id,'pending',nullif(trim(p_reason),''))
  returning * into v_request;
  return v_request;
end;
$$;

create or replace function public.cancel_account_deletion()
returns public.account_deletion_requests
language plpgsql
security definer
set search_path=''
as $$
declare v_request public.account_deletion_requests;
begin
  update public.account_deletion_requests
     set status='cancelled',cancelled_at=now(),updated_at=now()
   where user_id=(select auth.uid()) and status='pending'
   returning * into v_request;
  if not found then raise exception 'No pending deletion request found.'; end if;
  return v_request;
end;
$$;

