create or replace function public.review_account_deletion(p_request_id uuid,p_action text,p_note text default null)
returns public.account_deletion_requests
language plpgsql
security definer
set search_path=''
as $$
declare v_actor public.profiles; v_request public.account_deletion_requests;
begin
  select * into v_actor from public.profiles where id=(select auth.uid());
  if not found or v_actor.role <> 'super_admin'::public.user_role or v_actor.status <> 'active'::public.account_status then
    raise exception 'Only an active Super Admin may review account deletion requests.';
  end if;
  if p_action not in ('approve','reject') then raise exception 'Action must be approve or reject.'; end if;
  select * into v_request from public.account_deletion_requests where id=p_request_id for update;
  if not found then raise exception 'Deletion request not found.'; end if;
  if v_request.status <> 'pending' then raise exception 'Only pending deletion requests can be reviewed.'; end if;
  if p_action='approve' then
    update public.account_deletion_requests set status='approved',reviewed_by=v_actor.id,reviewed_at=now(),approved_at=now(),resolution_note=nullif(trim(p_note),''),
      resolved_at=null,updated_at=now() where id=p_request_id returning * into v_request;
    update public.profiles set status='suspended'::public.account_status,updated_at=now() where id=v_request.user_id and role='customer'::public.user_role;
    update public.customer_service_access set status='suspended' where user_id=v_request.user_id and status <> 'suspended';
    insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
      values(v_actor.id,'Approved account deletion request and revoked service access','corporate','account_deletion_request',p_request_id::text,
        jsonb_build_object('subject_user_id',v_request.user_id,'stage','approved_access_revoked'));
  else
    update public.account_deletion_requests set status='rejected',reviewed_by=v_actor.id,reviewed_at=now(),resolved_at=now(),
      resolution_note=nullif(trim(p_note),''),updated_at=now() where id=p_request_id returning * into v_request;
    insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
      values(v_actor.id,'Rejected account deletion request','corporate','account_deletion_request',p_request_id::text,
        jsonb_build_object('subject_user_id',v_request.user_id,'stage','rejected'));
  end if;
  return v_request;
end $$;

revoke all on function public.review_account_deletion(uuid,text,text) from public,anon;
grant execute on function public.review_account_deletion(uuid,text,text) to authenticated;

