create or replace function public.qa_create_acceptance_run(p_platform text,p_scenario text default 'non_financial_acceptance',p_payload jsonb default '{}'::jsonb)
returns public.qa_acceptance_runs
language plpgsql security definer set search_path=public
as $$
declare r public.qa_acceptance_runs;
begin
 if p_platform not in ('consult','engineering','host','print','fabrication','compute','academy','digital_business','business_centre','schoolpro','datasub') then raise exception 'Unsupported QA platform'; end if;
 if p_scenario ilike '%payment%' or p_scenario ilike '%purchase%' or p_scenario ilike '%settle%' or p_scenario ilike '%fulfil%' then raise exception 'Financial/provider/fulfilment scenarios are prohibited in QA harness'; end if;
 insert into public.qa_acceptance_runs(platform_code,scenario,payload,result)
 values(p_platform,p_scenario,coalesce(p_payload,'{}'::jsonb),
 jsonb_build_object('qa',true,'financial_actions',false,'provider_actions',false,'customer_data_written',false))
 returning * into r;
 return r;
end $$;
