create or replace function public.qa_mark_acceptance_run(p_run uuid,p_status text,p_result jsonb default '{}'::jsonb)
returns public.qa_acceptance_runs language plpgsql security definer set search_path=public as $$
declare r public.qa_acceptance_runs;
begin
 if p_status not in ('verified','failed') then raise exception 'QA result status must be verified or failed'; end if;
 update public.qa_acceptance_runs set status=p_status,result=result||coalesce(p_result,'{}'::jsonb)||jsonb_build_object('qa',true,'financial_actions',false,'provider_actions',false),updated_at=now() where id=p_run and status<>'cleaned' returning * into r;
 if r.id is null then raise exception 'QA run not found or already cleaned'; end if;
 return r;
end $$;
