create or replace function public.render_ihlink_template(p_platform text,p_type text,p_values jsonb default '{}'::jsonb)
returns table(template_id uuid,template_name text,rendered_content text,storage_path text)
language plpgsql security definer set search_path=public as $$
declare t public.ihlink_document_templates%rowtype;k text;v text;out_text text;
begin
 select * into t from public.ihlink_document_templates where platform_code=p_platform and template_type=p_type and is_active order by is_default desc,updated_at desc limit 1;
 if t.id is null then return; end if;
 out_text:=coalesce(t.content,'');
 for k,v in select key,value from jsonb_each_text(coalesce(p_values,'{}'::jsonb)) loop out_text:=replace(out_text,'{{'||k||'}}',v); end loop;
 return query select t.id,t.name,out_text,t.storage_path;
end$$;
grant execute on function public.render_ihlink_template(text,text,jsonb) to authenticated;

create or replace function public.resolve_ihlink_email_template(p_platform text,p_key text,p_values jsonb default '{}'::jsonb)
returns table(template_id uuid,template_name text,subject text,html_body text,text_body text)
language plpgsql security definer set search_path=public as $$
declare t public.ihlink_email_templates%rowtype;k text;v text;s text;h text;b text;
begin
 select * into t from public.ihlink_email_templates where platform_code=p_platform and template_key=p_key and is_active order by updated_at desc limit 1;
 if t.id is null then return; end if;s:=t.subject;h:=t.html_body;b:=t.text_body;
 for k,v in select key,value from jsonb_each_text(coalesce(p_values,'{}'::jsonb)) loop s:=replace(s,'{{'||k||'}}',v);h:=replace(h,'{{'||k||'}}',v);b:=replace(b,'{{'||k||'}}',v);end loop;
 return query select t.id,t.name,s,h,b;
end$$;
grant execute on function public.resolve_ihlink_email_template(text,text,jsonb) to authenticated;

create unique index if not exists finance_refund_requests_source_unique on public.finance_refund_requests(product,source_reference) where status in ('requested','approved','processing','processed');

create or replace function public.queue_failed_fulfilment_refund(p_product text,p_source_reference text,p_customer uuid,p_amount numeric,p_reason text)
returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid; v_settled boolean;
begin
 if p_amount<=0 then raise exception 'Refund amount must be positive'; end if;
 select exists(select 1 from public.payment_transactions where user_id=p_customer and platform_code=p_product and (transaction_ref=p_source_reference or provider_reference=p_source_reference) and is_settled=true and status in ('verified','credited')) into v_settled;
 if not v_settled then raise exception 'No verified settled payment matches this refund'; end if;
 select id into v_id from public.finance_refund_requests where product=p_product and source_reference=p_source_reference and status in ('requested','approved','processing','processed') limit 1;
 if v_id is not null then return v_id; end if;
 insert into public.finance_refund_requests(refund_number,product,source_reference,customer_user_id,amount,currency,reason,status,requested_by)
 values('RFD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),p_product,p_source_reference,p_customer,p_amount,'NGN',p_reason,'requested',p_customer)
 returning id into v_id;
 return v_id;
end$$;
revoke all on function public.queue_failed_fulfilment_refund(text,text,uuid,numeric,text) from public,anon,authenticated;

create or replace function public.my_payment_outcomes(p_platform text)
returns table(transaction_ref text,provider_reference text,amount numeric,status text,is_settled boolean,credited_at timestamptz,created_at timestamptz,refund_number text,refund_status text,refund_reason text)
language sql security definer set search_path=public as $$
 select p.transaction_ref,p.provider_reference,p.amount,
 case when r.status='processed' then 'refunded'
      when r.id is not null then 'refund_pending'
      when p.status='credited' then 'success'
      when p.status in ('failed','rejected') then 'failed'
      else 'pending' end,
 p.is_settled,p.credited_at,p.created_at,r.refund_number,r.status,r.reason
 from public.payment_transactions p
 left join lateral (select * from public.finance_refund_requests r where r.customer_user_id=auth.uid() and r.product=p.platform_code and (r.source_reference=p.transaction_ref or r.source_reference=p.provider_reference) order by r.created_at desc limit 1) r on true
 where p.user_id=auth.uid() and p.platform_code=p_platform
 order by p.created_at desc;
$$;
grant execute on function public.my_payment_outcomes(text) to authenticated;

create or replace function private.queue_refund_for_failed_fulfilment()
returns trigger language plpgsql security definer set search_path=public,private as $$
declare v_user uuid;v_platform text;v_amount numeric;v_ref text;v_paid boolean:=false;
begin
 if tg_table_name='host_orders' then
   if new.status not in ('failed','cancelled') and coalesce(new.provisioning_status,'') not in ('failed','cancelled') then return new; end if;
   if coalesce(new.payment_status,'')<>'paid' then return new; end if;
   v_user:=new.user_id;v_platform:='host';v_amount:=new.amount;v_paid:=true;
   select coalesce(transaction_ref,provider_reference) into v_ref from public.host_payments where invoice_id in(select id from public.host_invoices where order_id=new.id) and status='paid' order by paid_at desc nulls last limit 1;
 elsif tg_table_name='business_orders' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:=new.unit_code;v_amount:=new.amount;
   select coalesce(provider_reference,''),true into v_ref,v_paid from public.business_payments bp join public.business_invoices bi on bi.id=bp.invoice_id where bi.order_id=new.id and bp.status='paid' order by bp.paid_at desc nulls last limit 1;
 elsif tg_table_name='print_orders' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='print';
   select pi.amount,coalesce(pp.provider_reference,''),true into v_amount,v_ref,v_paid from public.print_invoices pi join public.print_payments pp on pp.invoice_id=pi.id where pi.order_id=new.id and pp.status='paid' order by pp.paid_at desc nulls last limit 1;
 elsif tg_table_name='consult_projects' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='consult';
   select cp.amount,coalesce(cp.payment_reference,''),true into v_amount,v_ref,v_paid from public.consult_payments cp where cp.project_id=new.id and cp.status='paid' order by cp.paid_at desc nulls last limit 1;
 elsif tg_table_name='engineering_projects' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='engineering';
   select ei.amount,coalesce(ep.provider_reference,''),true into v_amount,v_ref,v_paid from public.engineering_invoices ei join public.engineering_payments ep on ep.invoice_id=ei.id where ei.project_id=new.id and ep.status='paid' order by ep.paid_at desc nulls last limit 1;
 end if;
 if not coalesce(v_paid,false) or coalesce(v_ref,'')='' or coalesce(v_amount,0)<=0 then return new; end if;
 begin perform public.queue_failed_fulfilment_refund(v_platform,v_ref,v_user,v_amount,'Paid service fulfilment failed or was cancelled after verified settlement'); exception when others then null; end;
 return new;
end$$;

