create or replace function private.register_ihlink_document(p_platform text,p_type text,p_owner uuid,p_source_table text,p_source_id uuid,p_source_ref text,p_values jsonb)
returns uuid language plpgsql security definer set search_path=public,private as $$
declare t record;v_id uuid;v_no text;v_html text;k text;v text;vals jsonb;
begin
 select * into t from ihlink_document_templates where platform_code=p_platform and template_type=p_type and is_active order by is_default desc,updated_at desc limit 1;
 if t.id is null then return null;end if;
 select id into v_id from ihlink_generated_documents where platform_code=p_platform and document_type=p_type and source_table=p_source_table and source_id=p_source_id;
 if v_id is not null then return v_id;end if;
 v_no:=case when p_type='refund_receipt' then 'IHL-RFD-' else 'IHL-RCP-' end||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
 vals:=coalesce(p_values,'{}'::jsonb)||jsonb_build_object(case when p_type='refund_receipt' then 'refund_reference' else 'receipt_number' end,v_no);
 v_html:=coalesce(t.content,'');v_html:=replace(v_html,'{{logo_url}}','/brand/ihlink-icon.png?v=20260928-valid-logo4');
 for k,v in select key,value from jsonb_each_text(vals) loop v_html:=replace(v_html,'{{'||k||'}}',v);end loop;
 insert into ihlink_generated_documents(platform_code,document_type,template_id,owner_user_id,source_table,source_id,source_reference,document_number,merge_values,rendered_content,status,issued_at)
 values(p_platform,p_type,t.id,p_owner,p_source_table,p_source_id,p_source_ref,v_no,vals,v_html,'issued',now()) returning id into v_id;return v_id;
end$$;

create or replace function private.auto_register_shared_payment_receipt() returns trigger language plpgsql security definer set search_path=public,private as $$
declare vals jsonb;
begin
 if new.platform_code='datasub' or not coalesce(new.is_settled,false) or coalesce(new.status,'') not in('verified','credited','paid','success') then return new;end if;
 vals:=jsonb_build_object('customer_name','IHLink Customer','transaction_reference',coalesce(new.provider_reference,new.transaction_ref,new.id::text),'amount','₦'||to_char(new.amount,'FM999,999,999,990.00'),'payment_method',coalesce(new.method,'Verified payment'),'date',coalesce(new.credited_at,new.verified_at,new.created_at)::text,'service',replace(new.platform_code,'_',' '));
 perform private.register_ihlink_document(new.platform_code,'payment_receipt',new.user_id,tg_table_name,new.id,coalesce(new.provider_reference,new.transaction_ref,new.id::text),vals);return new;
end$$;
drop trigger if exists shared_payment_receipt_registry on public.payment_transactions;
create trigger shared_payment_receipt_registry after insert or update of status,is_settled on public.payment_transactions for each row execute function private.auto_register_shared_payment_receipt();

create or replace function private.auto_register_business_payment_receipt() returns trigger language plpgsql security definer set search_path=public,private as $$
declare platform text;vals jsonb;
begin
 if coalesce(new.status,'')<>'paid' then return new;end if;
 select bo.unit_code into platform from business_invoices bi join business_orders bo on bo.id=bi.order_id where bi.id=new.invoice_id;
 if platform is null then return new;end if;
 vals:=jsonb_build_object('customer_name','IHLink Customer','transaction_reference',coalesce(new.provider_reference,new.id::text),'amount','₦'||to_char(new.amount,'FM999,999,999,990.00'),'payment_method','Verified payment','date',coalesce(new.paid_at,new.created_at)::text,'service',replace(platform,'_',' '));
 perform private.register_ihlink_document(platform,'payment_receipt',new.user_id,tg_table_name,new.id,coalesce(new.provider_reference,new.id::text),vals);return new;
end$$;
drop trigger if exists business_payment_receipt_registry on public.business_payments;
create trigger business_payment_receipt_registry after insert or update of status on public.business_payments for each row execute function private.auto_register_business_payment_receipt();

create or replace function private.auto_register_refund_document() returns trigger language plpgsql security definer set search_path=public,private as $$
begin if new.status='processed' and (tg_op='INSERT' or old.status is distinct from new.status) then perform private.register_ihlink_document(new.product,'refund_receipt',new.customer_user_id,'finance_refund_requests',new.id,new.refund_number,jsonb_build_object('customer_name','IHLink Customer','refund_reference',new.refund_number,'transaction_reference',new.source_reference,'amount','₦'||to_char(new.amount,'FM999,999,999,990.00'),'reason',new.reason,'date',coalesce(new.processed_at,now())::text));end if;return new;end$$;
drop trigger if exists finance_refund_receipt_registry on public.finance_refund_requests;
create trigger finance_refund_receipt_registry after insert or update of status on public.finance_refund_requests for each row execute function private.auto_register_refund_document();

