create or replace function public.finalize_academy_payment(p_order uuid,p_transaction_ref text,p_amount numeric) returns uuid language plpgsql security definer set search_path=public as $$declare o public.academy_course_orders; e uuid;begin select * into o from public.academy_course_orders where id=p_order for update;if o.id is null then raise exception 'Academy order not found';end if;if p_amount<o.amount then raise exception 'Verified amount is below course fee';end if;if o.status='paid' then return o.enrollment_id;end if;insert into public.academy_enrollments(course_id,user_id,status,progress,order_id) values(o.course_id,o.user_id,'active',0,o.id) on conflict do nothing;select id into e from public.academy_enrollments where course_id=o.course_id and user_id=o.user_id order by enrolled_at desc limit 1;update public.academy_course_orders set status='paid',payment_reference=p_transaction_ref,paid_at=now(),enrollment_id=e,updated_at=now() where id=o.id;return e;end$$;
revoke all on function public.finalize_academy_payment(uuid,text,numeric) from public,anon,authenticated;
