drop function if exists public.finalize_academy_payment(uuid,text,numeric);
drop table if exists public.academy_course_orders;
create or replace function public.finalize_academy_course_order(p_order uuid) returns uuid language plpgsql security definer set search_path=public as $$declare o public.business_orders;e uuid;begin select * into o from public.business_orders where id=p_order and unit_code='academy' for update;if o.id is null then raise exception 'Academy order not found';end if;if o.status not in('paid','completed','in_production') then raise exception 'Academy order is not paid';end if;insert into public.academy_enrollments(course_id,user_id,status,progress,order_id) values(o.service_id,o.user_id,'active',0,o.id) on conflict(course_id,user_id) do update set status='active',order_id=excluded.order_id;select id into e from public.academy_enrollments where course_id=o.service_id and user_id=o.user_id;return e;end$$;
revoke all on function public.finalize_academy_course_order(uuid) from public,anon,authenticated;
grant execute on function public.finalize_academy_course_order(uuid) to service_role;

create or replace function public.apply_academy_course(target_course uuid) returns uuid language plpgsql set search_path='' as $$declare course public.academy_courses;request_id uuid;enrollment_id uuid;begin select * into course from public.academy_courses where id=target_course and is_active;if auth.uid() is null or course.id is null then raise exception 'Active course and authenticated account required';end if;select id into enrollment_id from public.academy_enrollments where course_id=course.id and user_id=auth.uid();if enrollment_id is not null then return enrollment_id;end if;insert into public.business_orders(user_id,unit_code,title,requirements,quantity,amount,specifications,status) values(auth.uid(),'academy','Enrolment: '||course.title,'Course enrolment for '||course.title,1,coalesce(course.fee,0),jsonb_build_object('course_id',course.id,'course_title',course.title,'course_fee',coalesce(course.fee,0)),case when coalesce(course.fee,0)>0 then 'awaiting_payment' else 'paid' end) returning id into request_id;if coalesce(course.fee,0)>0 then insert into public.business_invoices(order_id,invoice_number,amount,currency,status,amount_paid) values(request_id,'ACA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),course.fee,'NGN','issued',0);end if;insert into public.academy_enrollments(course_id,user_id,status,progress,order_id) values(course.id,auth.uid(),case when coalesce(course.fee,0)>0 then 'awaiting_payment' else 'active' end,0,request_id) returning id into enrollment_id;return enrollment_id;end$$;
create or replace function public.activate_paid_academy_enrollment() returns trigger language plpgsql security definer set search_path='' as $$begin if new.unit_code='academy' and new.status='paid' and old.status is distinct from new.status then update public.academy_enrollments set status='active' where order_id=new.id and status in('applied','awaiting_payment','pending');insert into public.business_notifications(user_id,unit_code,title,body) values(new.user_id,'academy','Course access activated','Your Academy payment is verified and course access is now active.');end if;return new;end$$;
drop trigger if exists academy_activate_after_paid_order on public.business_orders;
create trigger academy_activate_after_paid_order after update of status on public.business_orders for each row execute function public.activate_paid_academy_enrollment();

create or replace function public.schoolpro_issue_library_loan(p_school uuid,p_book uuid,p_student uuid default null,p_member uuid default null,p_due timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$declare b schoolpro_library_books;l uuid;begin if not private.is_admin(array['super_admin']::public.user_role[]) and not schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;if (p_student is null)=(p_member is null) then raise exception 'Choose exactly one borrower';end if;select * into b from schoolpro_library_books where id=p_book and school_id=p_school for update;if b.id is null or b.available_copies<1 then raise exception 'Book unavailable';end if;insert into schoolpro_library_loans(school_id,book_id,student_id,member_id,due_at,fine,status) values(p_school,p_book,p_student,p_member,p_due,0,'borrowed') returning id into l;update schoolpro_library_books set available_copies=available_copies-1 where id=p_book;return l;end$$;
create or replace function public.schoolpro_return_library_loan(p_loan uuid) returns void language plpgsql security definer set search_path=public as $$declare l schoolpro_library_loans;begin select * into l from schoolpro_library_loans where id=p_loan for update;if l.id is null then raise exception 'Loan not found';end if;if not private.is_admin(array['super_admin']::public.user_role[]) and not schoolpro_member_can_manage(l.school_id) then raise exception 'Not authorized';end if;if l.status='returned' then return;end if;update schoolpro_library_loans set status='returned',returned_at=now() where id=l.id;update schoolpro_library_books set available_copies=least(copies,available_copies+1) where id=l.book_id;end$$;
create or replace function public.schoolpro_allocate_hostel(p_school uuid,p_student uuid,p_room uuid,p_session text) returns uuid language plpgsql security definer set search_path=public as $$declare rm schoolpro_hostel_rooms;a uuid;begin if not private.is_admin(array['super_admin']::public.user_role[]) and not schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;select * into rm from schoolpro_hostel_rooms where id=p_room and school_id=p_school for update;if rm.id is null or rm.occupied>=rm.capacity then raise exception 'Room is full or unavailable';end if;insert into schoolpro_hostel_allocations(school_id,student_id,room_id,session,active) values(p_school,p_student,p_room,p_session,true) returning id into a;update schoolpro_hostel_rooms set occupied=occupied+1 where id=p_room;return a;end$$;
create or replace function public.schoolpro_vacate_hostel(p_allocation uuid) returns void language plpgsql security definer set search_path=public as $$declare a schoolpro_hostel_allocations;begin select * into a from schoolpro_hostel_allocations where id=p_allocation for update;if a.id is null then raise exception 'Allocation not found';end if;if not private.is_admin(array['super_admin']::public.user_role[]) and not schoolpro_member_can_manage(a.school_id) then raise exception 'Not authorized';end if;if not a.active then return;end if;update schoolpro_hostel_allocations set active=false where id=a.id;update schoolpro_hostel_rooms set occupied=greatest(0,occupied-1) where id=a.room_id;end$$;
revoke all on function public.schoolpro_issue_library_loan(uuid,uuid,uuid,uuid,timestamptz) from public,anon;grant execute on function public.schoolpro_issue_library_loan(uuid,uuid,uuid,uuid,timestamptz) to authenticated;
revoke all on function public.schoolpro_return_library_loan(uuid) from public,anon;grant execute on function public.schoolpro_return_library_loan(uuid) to authenticated;
revoke all on function public.schoolpro_allocate_hostel(uuid,uuid,uuid,text) from public,anon;grant execute on function public.schoolpro_allocate_hostel(uuid,uuid,uuid,text) to authenticated;
revoke all on function public.schoolpro_vacate_hostel(uuid) from public,anon;grant execute on function public.schoolpro_vacate_hostel(uuid) to authenticated;
